import{_ as a,o as n,c as i,a2 as r}from"./chunks/framework.CDpkVv68.js";const m=JSON.parse('{"title":"Carpentry","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/carpentry.md","filePath":"es/guide/professions/carpentry.md"}'),s={name:"es/guide/professions/carpentry.md"};function o(t,e,c,l,d,p){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="carpentry" tabindex="-1">Carpentry <a class="header-anchor" href="#carpentry" aria-label="Enlace permanente a &quot;Carpentry&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto.</strong> Esta página describe el rediseño previsto, no mecánicas confirmadas en juego. <strong>Implementación/disponibilidad:</strong> no establecidas para este rediseño. <strong>Verificación:</strong> solo revisión documental. <strong>Revisado:</strong> 2026-10-08 respecto a la <a href="/Syrolands-Public/es/game-design/professions/carpentry.html">especificación completa del diseño</a>.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Carpentry convierte el conocimiento de la madera en equipo, construcción y estructuras útiles sobre el terreno.</li><li>Bowmaking es una vía de técnicas aprendidas de Carpentry/Archery, no una recompensa automática de habilidad.</li><li>La preparación de materiales y los ensamblajes importan; las reglas de construcción y migración siguen abiertas.</li></ul><h2 id="what-it-does" tabindex="-1">Qué hace <a class="header-anchor" href="#what-it-does" aria-label="Enlace permanente a &quot;Qué hace&quot;">​</a></h2><p>Carpentry transforma la madera mediante secado, selección, corte, conformado, unión, montaje y acabado. Veta, humedad, ensamblajes y tratamiento deberían importar sin exigir una simulación microscópica de carpintería.</p><h2 id="why-take-it-into-the-field" tabindex="-1">¿Por qué llevarla al terreno? <a class="header-anchor" href="#why-take-it-into-the-field" aria-label="Enlace permanente a &quot;¿Por qué llevarla al terreno?&quot;">​</a></h2><p>Los productos, en estado Propuesto, van desde muebles, recipientes y mangos de armas hasta escudos, estructuras de campamento, soportes de minas, puentes y fortificaciones. Camping, <a href="/Syrolands-Public/es/guide/professions/mining.html">Mining</a>, <a href="/Syrolands-Public/es/guide/professions/blacksmithing.html">Blacksmithing</a> y <a href="/Syrolands-Public/es/guide/professions/tinkering.html">Tinkering</a> crean colaboraciones útiles; las reglas de colocación y protección siguen abiertas.</p><h2 id="bowmaking-and-fletching" tabindex="-1">Bowmaking y Fletching <a class="header-anchor" href="#bowmaking-and-fletching" aria-label="Enlace permanente a &quot;Bowmaking y Fletching&quot;">​</a></h2><p>Bowmaking es una vía de técnicas aprendidas basada principalmente en Carpentry y Archery, con apoyo opcional de Tailoring y Blacksmithing. No es una habilidad independiente en esta propuesta, y la Carpentry ordinaria no la enseña automáticamente. Seleccionar y secar una duela, darle forma, equilibrar la flexión, encordar, ajustar y realizar disparos de prueba construyen una identidad de Master Bowyer. Las flechas combinan astiles, puntas, emplumado y montaje; sus funciones exactas siguen siendo propuestas. La conciliación con cualquier habilidad Bowcraft existente continúa pendiente.</p><h2 id="learning-and-specialization" tabindex="-1">Aprendizaje y especialización <a class="header-anchor" href="#learning-and-specialization" aria-label="Enlace permanente a &quot;Aprendizaje y especialización&quot;">​</a></h2><p>Un Woodworker’s Journal registra materiales y técnicas aprendidos de maestros, manuscritos, desafíos y exploración. Se aplican la <a href="/Syrolands-Public/es/guide/professions/overview.html">progresión y los lotes compartidos</a>. Construction y Bowmaking ofrecen vías; Luthiery y los componentes navales siguen siendo direcciones futuras. <a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Lumberjacking</a> aporta conocimiento de la madera, mientras la <a href="/Syrolands-Public/es/guide/items/item-quality.html">calidad de objetos</a> describe los límites de los resultados.</p><p><a href="/Syrolands-Public/es/guide/professions/overview.html">Todas las profesiones</a> · <a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Especificación completa del diseño</a></p>',13)])])}const h=a(s,[["render",o]]);export{m as __pageData,h as default};
